using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Data;using System.Windows.Markup;using System.Windows.Media;
namespace FileCompass {
 internal static class DrawerControls {
  internal static readonly Style ActionStyle=BuildActionStyle();
  static Style BuildActionStyle(){var style=new Style(typeof(Button));style.Setters.Add(new Setter(Control.ForegroundProperty,Brushes.White));style.Setters.Add(new Setter(Control.BackgroundProperty,Brushes.Transparent));style.Setters.Add(new Setter(Control.FontSizeProperty,14.0));style.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Left));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(12,8,12,8)));style.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,2,0,2)));style.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Border x:Name='Frame' Background='{TemplateBinding Background}' BorderBrush='Transparent' BorderThickness='3,0,0,0' CornerRadius='5' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='{TemplateBinding HorizontalContentAlignment}' VerticalAlignment='Center' TextElement.Foreground='White' TextElement.FontSize='{TemplateBinding FontSize}'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Frame' Property='Background' Value='#315B80'/><Setter TargetName='Frame' Property='BorderBrush' Value='#A8DAFF'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Frame' Property='Background' Value='#176BAA'/><Setter TargetName='Frame' Property='BorderBrush' Value='#A8DAFF'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.45'/></Trigger></ControlTemplate.Triggers></ControlTemplate>")));return style;}
  internal static Button Action(string title,Action action){var button=new Button{Content=title,Style=ActionStyle};button.Click+=delegate{action();};return button;}
  internal static Expander Group(MenuItem original,Action close){var body=new StackPanel{Margin=new Thickness(10,2,0,4)};var group=new Expander{Header=new TextBlock{Text=Convert.ToString(original.Header).Replace("_",""),Foreground=Brushes.White,FontSize=14},Content=body,Foreground=Brushes.White,Margin=new Thickness(0,3,0,3)};group.Template=(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Expander'><StackPanel><ToggleButton HorizontalAlignment='Stretch' HorizontalContentAlignment='Stretch' IsChecked='{Binding IsExpanded,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border x:Name='Head' Background='#203F5F' CornerRadius='5' Padding='12,9'><DockPanel><TextBlock x:Name='Arrow' DockPanel.Dock='Right' Text='›' Foreground='White'/><ContentPresenter TextElement.Foreground='White' TextElement.FontSize='{TemplateBinding FontSize}'/></DockPanel></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Head' Property='Background' Value='#315B80'/></Trigger><Trigger Property='IsChecked' Value='True'><Setter TargetName='Head' Property='Background' Value='#176BAA'/><Setter TargetName='Arrow' Property='Text' Value='⌄'/></Trigger></ControlTemplate.Triggers></ControlTemplate></ToggleButton.Template><ContentPresenter ContentSource='Header'/></ToggleButton><ContentPresenter x:Name='Body' ContentSource='Content' Visibility='Collapsed'/></StackPanel><ControlTemplate.Triggers><Trigger Property='IsExpanded' Value='True'><Setter TargetName='Body' Property='Visibility' Value='Visible'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");
   group.Expanded+=delegate(object sender,RoutedEventArgs e){if(!Object.ReferenceEquals(e.OriginalSource,group))return;original.RaiseEvent(new RoutedEventArgs(MenuItem.SubmenuOpenedEvent));body.Children.Clear();foreach(object entry in original.Items){var item=entry as MenuItem;if(item==null){if(entry is Separator)body.Children.Add(new Border{Height=1,Background=CompactTheme.ColorBrush("#42617C"),Margin=new Thickness(8,7,8,7)});continue;}if(item.HasItems){body.Children.Add(Group(item,close));continue;}var captured=item;string text=Convert.ToString(item.Header).Replace("_","");if(item.IsCheckable)text=(item.IsChecked?"✓ ":"○ ")+text;if(!String.IsNullOrEmpty(item.InputGestureText))text+="  ·  "+item.InputGestureText;var button=Action(text,delegate{close();if(captured.IsCheckable)captured.IsChecked=!captured.IsChecked;if(captured.Command!=null){if(captured.Command.CanExecute(captured.CommandParameter))captured.Command.Execute(captured.CommandParameter);}else captured.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent,captured));});button.SetBinding(UIElement.IsEnabledProperty,new Binding("IsEnabled"){Source=item});button.SetBinding(UIElement.VisibilityProperty,new Binding("Visibility"){Source=item});body.Children.Add(button);}};return group;}
 }
}
